tags: [test-design, test-doubles, fakes, test-isolation, static-state]
code:
  language: csharp
  harness: statements
  source: |
    TestAddOne();
    TestAddTwo();

    static void TestAddOne()
    {
        var repo = new FakeOrderRepository();
        repo.Add("A");
        Console.WriteLine(repo.Count() == 1 ? "PASS" : "FAIL");
    }

    static void TestAddTwo()
    {
        var repo = new FakeOrderRepository();
        repo.Add("B");
        repo.Add("C");
        Console.WriteLine(repo.Count() == 2 ? "PASS" : "FAIL");
    }

    class FakeOrderRepository
    {
        private static readonly List<string> Items = new();

        public void Add(string item) => Items.Add(item);

        public int Count() => Items.Count;
    }
bugLineSets: [[21]]
fixedSource: |
  TestAddOne();
  TestAddTwo();

  static void TestAddOne()
  {
      var repo = new FakeOrderRepository();
      repo.Add("A");
      Console.WriteLine(repo.Count() == 1 ? "PASS" : "FAIL");
  }

  static void TestAddTwo()
  {
      var repo = new FakeOrderRepository();
      repo.Add("B");
      repo.Add("C");
      Console.WriteLine(repo.Count() == 2 ? "PASS" : "FAIL");
  }

  class FakeOrderRepository
  {
      private readonly List<string> _items = new();

      public void Add(string item) => _items.Add(item);

      public int Count() => _items.Count;
  }
fixedExpect: { kind: output, value: "PASS\nPASS" }
